// src/utils/topologyMapper.js

const edgeDefaults = {
  animated: true,
  style: { stroke: '#4A5B6E', strokeWidth: 2 },
  labelStyle: { fill: '#A0AEC0', fontWeight: 500, fontSize: '11px' },
  labelShowBg: true,
  labelBgStyle: { fill: '#23303D', stroke: '#4A5B6E' },
  labelBgPadding: [4, 4],
};

/**
 * Process ONT serial search through 4 JSON files
 * @param {string} ontSerialNo - ONT serial number to search
 * @param {Array} file1 - ONT2OLT data
 * @param {Array} file2 - OLT2Router data  
 * @param {Array} file3 - child2parent data
 * @param {Array} file4 - GPtopology data
 * @returns {Object|null} - { nodes, edges } for React Flow or null if not found
 */
export function processOntSearch(ontSerialNo, file1, file2, file3, file4) {
  // Step 1: Find ONT in File 1 (ONT2OLT)
  const ontEntry = file1.find(ont => ont.ont_serial_no?.trim() === ontSerialNo?.trim());
  if (!ontEntry) return null;
  
  const { olt_hostname } = ontEntry;
  if (!olt_hostname) return null;
  
  // Step 2: Filter File 2 (OLT2Router) by olt_hostname
  const oltEntries = file2.filter(entry => entry.olt_hostname === olt_hostname);
  const mandalRouters = [...new Set(
    oltEntries
      .map(e => e.mandal_router_hostname)
      .filter(h => h && h.trim() !== '')
  )];
  
  if (mandalRouters.length === 0) return null;
  const primaryMandalRouter = mandalRouters[0];
  
  // Step 3: Filter File 3 (child2parent) by mandal_router_hostname, get unique topologies
  const file3Filtered = file3.filter(entry => 
    mandalRouters.includes(entry.mandal_router_hostname)
  );
  const uniqueTopologies = [...new Set(
    file3Filtered.map(e => e.topology).filter(t => t && t.trim() !== '')
  )];
  
  if (uniqueTopologies.length === 0) return null;
  
  // Step 4: Filter File 4 (GPtopology) by gp_ring_name matching unique topologies
  const ringData = file4.filter(entry => 
    uniqueTopologies.includes(entry.gp_ring_name)
  );
  
  if (ringData.length === 0) return null;
  
  // Convert to React Flow nodes and edges
  return buildRingTopologyFromData(ringData, primaryMandalRouter, uniqueTopologies);
}

/**
 * Build React Flow nodes/edges from ring topology data
 */
export function buildRingTopologyFromData(ringData, centralRouterHostname, topologyNames = []) {
  const devices = new Map();
  const cx = 400, cy = 260, radius = 200;
  
  // Add central mandal router at center
  const centralMandalIp = ringData.find(d => 
    d.mandal_host_name === centralRouterHostname || d.Mandal_router_ip
  )?.Mandal_router_ip || '';
  
  devices.set(centralRouterHostname, {
    id: `mandal-${centralRouterHostname}`,
    type: 'fiberDevice',
    position: { x: cx - 60, y: cy - 30 },
    data: { 
      type: 'router', 
      hostname: centralRouterHostname,
      ip: centralMandalIp,
      isCentral: true,
      topology: topologyNames.join(', ')
    },
    style: { border: '3px solid #63b3ed', boxShadow: '0 0 15px rgba(99,179,237,0.7)' }
  });
  
  // Collect all GP routers from ring edges
  ringData.forEach(edge => {
    // A-end device
    if (edge.a_end_device !== centralRouterHostname && !devices.has(edge.a_end_device)) {
      devices.set(edge.a_end_device, {
        id: `gp-${edge.a_end_device}`,
        type: 'fiberDevice',
        data: {
          type: 'router',
          hostname: edge.a_end_device,
          ip: edge.a_end_device_ip,
          interface: edge.a_end_device_interface,
          ringName: edge.gp_ring_name
        }
      });
    }
    // B-end device  
    if (edge.b_end_device !== centralRouterHostname && !devices.has(edge.b_end_device)) {
      devices.set(edge.b_end_device, {
        id: `gp-${edge.b_end_device}`,
        type: 'fiberDevice',
        data: {
          type: 'router',
          hostname: edge.b_end_device,
          ip: edge.b_end_device_ip,
          interface: edge.b_end_device_interface,
          ringName: edge.gp_ring_name
        }
      });
    }
  });
  
  // Position GP routers in a ring around central node
  const gpNodes = Array.from(devices.values()).filter(n => !n.data.isCentral);
  const total = gpNodes.length;
  
  const positionedNodes = [
    // Central node first
    devices.get(centralRouterHostname),
    // GP routers in circular layout
    ...gpNodes.map((node, i) => {
      const angleDeg = (360 / Math.max(total, 1)) * i;
      const angleRad = (angleDeg * Math.PI) / 180;
      return {
        ...node,
        position: {
          x: cx + radius * Math.cos(angleRad) - 60,
          y: cy + radius * Math.sin(angleRad) - 30,
        }
      };
    })
  ];
  
  // Build edges from ringData
  const edges = ringData.map((edge, idx) => {
    const sourceId = edge.a_end_device === centralRouterHostname 
      ? `mandal-${centralRouterHostname}` 
      : `gp-${edge.a_end_device}`;
    const targetId = edge.b_end_device === centralRouterHostname
      ? `mandal-${centralRouterHostname}`
      : `gp-${edge.b_end_device}`;
      
    return {
      id: `ring-edge-${idx}-${edge.gp_ring_name}`,
      source: sourceId,
      target: targetId,
      label: edge.linear_ring || 'Ring',
      ...edgeDefaults
    };
  });
  
  return { nodes: positionedNodes, edges };
}

/**
 * Static ring builder for manual router drill-down (preserves original behavior)
 */
export function buildStaticRingTopology(clickedNode, siblings = []) {
  const defaultSiblings = [
    { id: `${clickedNode.id}-peer1`, hostname: 'peer-router-01', ip: '10.0.0.1' },
    { id: `${clickedNode.id}-peer2`, hostname: 'peer-router-02', ip: '10.0.0.2' },
    { id: `${clickedNode.id}-peer3`, hostname: 'peer-router-03', ip: '10.0.0.3' },
    { id: `${clickedNode.id}-peer4`, hostname: 'peer-router-04', ip: '10.0.0.4' },
  ];
  
  const allNodes = [clickedNode, ...(siblings.length ? siblings : defaultSiblings).map(s => ({
    id: s.id,
    type: 'fiberDevice',
    data: { type: 'router', hostname: s.hostname, ip: s.ip },
    position: { x: 0, y: 0 }
  }))];
  
  const cx = 400, cy = 260, radius = 200;
  const total = allNodes.length;
  
  const ringNodes = allNodes.map((node, i) => {
    const angleDeg = (360 / total) * i - 90;
    const angleRad = (angleDeg * Math.PI) / 180;
    return {
      ...node,
      position: {
        x: cx + radius * Math.cos(angleRad) - 60,
        y: cy + radius * Math.sin(angleRad) - 30,
      },
      style: node.id === clickedNode.id
        ? { border: '2px solid #63b3ed', boxShadow: '0 0 12px rgba(99,179,237,0.5)' }
        : {}
    };
  });
  
  const ringEdges = ringNodes.map((node, i) => {
    const next = ringNodes[(i + 1) % ringNodes.length];
    return {
      id: `ring-edge-${i}`,
      source: node.id,
      target: next.id,
      label: '10G Ring',
      ...edgeDefaults
    };
  });
  
  return { ringNodes, ringEdges };
}
